        "points": {
          "$ref": "#/definitions/questionPoints"
        },
        "qid": {
          "$ref": "#/definitions/questionQID"
        },
        "qids": {
          "description": "Array of possible qids for a question.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/definitions/questionQID"
          }
        }
      },
      "required": [
        "points"
      ],
      "oneOf": [
        {
          "type": "object",
          "required": [
            "qid"
          ]
        },
        {
          "type": "object",
          "required": [
            "qids"
          ]
        }
      ]
    },
    "questionPoints": {
      "description": "An array of points values.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "integer"
      }
    },
    "questionQID": {
      "description": "Question ID.",
      "type": "string"
    }
  }
